export const NATIVE_CARD_THEME_CSS = "@layer default {\n  /* 浅映卡片 · Soft Light */\n  .event-area {\n    --card-surface: #fffefa;\n    --card-sheen: #ffffffbf;\n    --card-shadow: #4036250b;\n    --card-edge: #00000014;\n    --text-body: #19201d;\n    --text-secondary: #47524d;\n    --text-muted: #56625c;\n    --card-gold: #765608;\n    background: transparent;\n    border: 0;\n    border-radius: 0;\n    --event-default-line-height: 1.5;\n    box-shadow: none;\n    --text-name: rgb(25, 39, 59);\n  }\n  .dark .event-area {\n    --text-name: rgb(222, 225, 229);\n    --card-surface: #1b211e;\n    --card-sheen: #ffffff09;\n    --card-shadow: #00000029;\n    --card-edge: #ffffff12;\n    --text-body: #e9eeec;\n    --text-secondary: #aab5b0;\n    --text-muted: #939e98;\n    --card-gold: #ebcb6b;\n  }\n  /* 列表留白保护头像框、圆角和阴影，事件本身不增加外边距。 */\n  .event-list {\n    padding: calc(var(--event-font-size) * 0.25);\n  }\n  .event .repeat-count {\n    padding: 0 calc(var(--event-font-size) * 0.375);\n  }\n\n  /* 公共尺寸与主题颜色 */\n  .event.type-gift {\n    --card-tone: var(--card-gold);\n    --card-fill:\n      linear-gradient(var(--card-sheen), transparent calc(var(--event-font-size) * 2)), #f5f2e9;\n  }\n\n  .dark .event.type-gift {\n    --card-fill:\n      linear-gradient(var(--card-sheen), transparent calc(var(--event-font-size) * 2)), #272b23;\n  }\n\n  .dark .event.type-superchat {\n    --card-fill: #262a28;\n    --card-tone: var(--price-color, #d6afbf);\n  }\n  .event.type-redpocket {\n    --card-tone: #af3520;\n  }\n  .dark .event.type-redpocket {\n    --card-tone: #dca18e;\n  }\n  .event.type-lottery {\n    --card-tone: #5125ff;\n  }\n  .dark .event.type-lottery {\n    --card-tone: rgb(185, 133, 244);\n  }\n  .event.guard-purchase-level-3 {\n    --card-tone: #235799;\n    --card-fill:\n      linear-gradient(var(--card-sheen), transparent calc(var(--event-font-size) * 2)), #f0f2f3;\n    --card-outline:\n      inset 0 0 0 calc(var(--event-font-size) * 1 / 16) #1a40713e,\n      0 calc(var(--event-font-size) * 2 / 16) calc(var(--event-font-size) * 4 / 16)\n        var(--card-shadow);\n  }\n\n  .dark .event.guard-purchase-level-3 {\n    --card-fill:\n      linear-gradient(var(--card-sheen), transparent calc(var(--event-font-size) * 2)), #232a29;\n    --card-outline:\n      inset 0 0 0 calc(var(--event-font-size) * 1 / 16) #becfe12e,\n      0 calc(var(--event-font-size) * 2 / 16) calc(var(--event-font-size) * 4 / 16)\n        var(--card-shadow);\n    --card-tone: #9cb6d2;\n  }\n  .event.guard-purchase-level-2 {\n    --card-tone: #5c3f9b;\n    --card-fill:\n      linear-gradient(var(--card-sheen), transparent calc(var(--event-font-size) * 2)), #efebf0;\n    --card-outline:\n      inset 0 0 0 calc(var(--event-font-size) * 1 / 16) #4d348156,\n      0 calc(var(--event-font-size) * 2 / 16) calc(var(--event-font-size) * 4 / 16)\n        var(--card-shadow);\n  }\n\n  .dark .event.guard-purchase-level-2 {\n    --card-fill:\n      linear-gradient(var(--card-sheen), transparent calc(var(--event-font-size) * 2)), #292e2e;\n    --card-outline:\n      inset 0 0 0 calc(var(--event-font-size) * 1 / 16) #c9bfdd41,\n      0 calc(var(--event-font-size) * 2 / 16) calc(var(--event-font-size) * 4 / 16)\n        var(--card-shadow);\n    --card-tone: #baadd3;\n  }\n  .event.guard-purchase-level-1 {\n    --card-tone: #944c07;\n    --card-fill:\n      linear-gradient(var(--card-sheen), transparent calc(var(--event-font-size) * 2)), #f1e7da;\n    --card-outline:\n      inset 0 0 0 calc(var(--event-font-size) * 1 / 16) #86450677,\n      0 calc(var(--event-font-size) * 2 / 16) calc(var(--event-font-size) * 4 / 16)\n        var(--card-shadow);\n  }\n\n  .dark .event.guard-purchase-level-1 {\n    --card-fill:\n      linear-gradient(var(--card-sheen), transparent calc(var(--event-font-size) * 2)), #34342c;\n    --card-outline:\n      inset 0 0 0 calc(var(--event-font-size) * 1 / 16) #debb9a63,\n      0 calc(var(--event-font-size) * 2 / 16) calc(var(--event-font-size) * 4 / 16)\n        var(--card-shadow);\n    --card-tone: #d9b28c;\n  }\n\n  /* 公共卡面。尺寸由基准字号派生，部件仍接受原有自定义变量。 */\n  .event {\n    --event-text-color: var(--text-body);\n    --event-secondary-color: var(--message-color, var(--text-secondary));\n    --event-muted-color: var(--message-color, var(--text-muted));\n    --card-tone: var(--text-secondary);\n    --card-tint: 7%;\n    --card-ring: 18%;\n    --card-fill:\n      linear-gradient(var(--card-sheen), transparent calc(var(--event-font-size) * 2)),\n      color-mix(in srgb, var(--card-tone) var(--card-tint), var(--card-surface));\n    --card-outline:\n      inset 0 0 0 calc(var(--event-font-size) / 16)\n        color-mix(in srgb, var(--card-tone) var(--card-ring), var(--card-edge)),\n      0 calc(var(--event-font-size) * 0.125) calc(var(--event-font-size) * 0.25) var(--card-shadow);\n    font-size: var(--event-font-size);\n    line-height: var(--event-line-height, 1.5);\n    color: var(--message-color, var(--text-body));\n    padding: var(--event-padding, calc(var(--event-font-size) * 0.5))\n      var(--event-padding, calc(var(--event-font-size) * 0.75));\n    border: 0;\n    border-radius: calc(var(--event-font-size) * 0.625);\n    background: var(--event-background, var(--event-background-color, var(--card-fill)));\n    box-shadow: var(--card-outline);\n    isolation: isolate;\n  }\n  .dark .event {\n    --card-tint: 6%;\n    --card-ring: 12%;\n  }\n  .event.price-gradient-active {\n    --card-tone: var(--price-color);\n    --price-gradient-background:\n      linear-gradient(var(--card-sheen), transparent calc(var(--event-font-size) * 2)),\n      color-mix(in srgb, var(--card-tone) var(--card-tint), var(--price-tier-background-color));\n  }\n  .event .price {\n    font-family: inherit;\n    font-size: var(--price-font-size, inherit);\n    line-height: inherit;\n    color: var(--price-color, var(--card-tone));\n    font-weight: 700;\n  }\n  .event :is(.gift-name, .guard-name, .honor-highlight) {\n    color: var(--message-color, var(--card-tone));\n  }\n  .event .blind-profit {\n    font-family: inherit;\n    font-weight: 700;\n  }\n\n  /* 弹幕：头像在卡面外，姓名与正文共用右侧卡面。 */\n  .event-list .event.type-chat {\n    display: inline-grid;\n    grid-template-columns: minmax(0, 1fr);\n    width: fit-content;\n    max-width: 100%;\n    padding: 0;\n    background: none;\n    box-shadow: none;\n    column-gap: var(--event-gap, calc(var(--event-font-size) * 0.5));\n    row-gap: 0;\n  }\n  .event-list .event.type-chat:has(> .avatar-wrap) {\n    grid-template-columns: auto minmax(0, 1fr);\n    padding-left: var(--event-padding, calc(var(--event-font-size) * 0.25));\n  }\n  .event-list .event.type-chat > .avatar-wrap {\n    grid-column: 1;\n    grid-row: 1 / span 2;\n    align-self: start;\n    width: var(--avatar-size, calc(var(--event-font-size) * 2));\n    height: var(\n      --avatar-height,\n      var(--avatar-size, calc(var(--event-font-size) * 2))\n    );\n    margin: calc(var(--event-font-size) * 0.25) 0 0;\n  }\n  .event-list .event.type-chat::before {\n    content: \"\";\n    display: block;\n    grid-column: -2;\n    grid-row: 1 / span 3;\n    z-index: -1;\n    border: calc(var(--event-font-size) / 16) solid var(--card-edge);\n    border-radius: calc(var(--event-font-size) * 0.625);\n    background: var(\n      --event-background,\n      var(\n        --event-background-color,\n        linear-gradient(var(--card-sheen), transparent calc(var(--event-font-size) * 1.75))\n          var(--card-surface)\n      )\n    );\n    box-shadow: 0 calc(var(--event-font-size) * 0.125) calc(var(--event-font-size) * 0.25)\n      var(--card-shadow);\n  }\n  .event-list .event.type-chat > .user {\n    grid-column: -2;\n    grid-row: 1;\n    max-width: 100%;\n    min-height: 0;\n    padding: var(--event-padding, calc(var(--event-font-size) * 0.5))\n      var(--event-padding, calc(var(--event-font-size) * 0.625)) 0;\n    margin: 0;\n  }\n  .event-list .event.type-chat > .content {\n    grid-column: -2;\n    grid-row: 2;\n    display: block;\n    padding: calc(var(--event-font-size) * 0.125)\n      var(--event-padding, calc(var(--event-font-size) * 0.625))\n      var(--event-padding, calc(var(--event-font-size) * 0.5));\n    line-height: var(--event-line-height, 1.5);\n  }\n  .event-list .event.type-chat > .time {\n    grid-column: -2;\n    grid-row: 3;\n    display: block;\n    margin: 0 calc(var(--event-font-size) * 0.625)\n      calc(var(--event-font-size) * 0.5);\n    padding: 0;\n    font-size: calc(var(--event-font-size) * 0.875);\n  }\n  .event-list .event.type-chat > .time.time-inline {\n    position: absolute;\n    right: var(--time-edge-right);\n    bottom: var(--event-padding, calc(var(--event-font-size) * 0.5));\n    margin: 0;\n  }\n  .event-list .event.type-chat:has(> .time:not(.time-inline)) > .content {\n    padding-bottom: calc(var(--event-font-size) * 0.25);\n  }\n  .event-list .event.type-chat:has(:is(.big-emote, .banner-emote)) .repeat-count {\n    display: table;\n    margin: calc(var(--event-font-size) * 0.25) 0 0;\n  }\n\n  /* 互动沿用自然行流，不画卡面。 */\n  .event-list .event.type-interaction {\n    font-size: calc(var(--event-font-size) * 0.875);\n    padding: var(--event-padding, calc(var(--event-font-size) * 0.25))\n      var(--event-padding, calc(var(--event-font-size) * 0.75));\n    background: var(--event-background, transparent);\n    box-shadow: none;\n  }\n  .event-list .event.type-interaction > :is(.avatar-wrap, .user) {\n    vertical-align: middle;\n  }\n\n  .event-list .event.type-interaction > .avatar-wrap {\n    width: var(--avatar-size, calc(var(--event-font-size) * 1.5));\n    height: var(--avatar-height, var(--avatar-size, calc(var(--event-font-size) * 1.5)));\n    margin-right: var(--event-gap, calc(var(--event-font-size) * 0.5));\n  }\n  .event-list .event.type-interaction:has(> .avatar-wrap) > .user {\n    max-width: calc(100% - var(--avatar-size, var(--event-font-size) * 1.5)\n      - var(--event-gap, var(--event-font-size) * 0.5)\n      - var(--event-gap, var(--event-font-size) * 0.25));\n  }\n  .event-list .event.type-interaction .username {\n    font-size: var(--event-font-size);\n  }\n\n  /* 礼物与大航海：头像跨两行，购买信息内部仍可用 order 调整顺序。 */\n  .event-list .event:is(.type-gift, .type-guard) {\n    display: grid;\n    grid-template-columns: minmax(0, 1fr);\n    gap: var(--event-gap, calc(var(--event-font-size) * 0.125))\n      var(--event-gap, calc(var(--event-font-size) * 0.75));\n    align-items: center;\n    padding-right: calc(\n      var(--gift-icon-size, calc(var(--event-font-size) * 2)) + calc(var(--event-font-size) * 5.5)\n    );\n  }\n  .event-list .event:is(.type-gift, .type-guard):has(> .avatar-wrap) {\n    grid-template-columns: auto minmax(0, 1fr);\n  }\n  .event-list .event:is(.type-gift, .type-guard) > .avatar-wrap {\n    grid-row: 1 / span 2;\n    align-self: center;\n    width: var(--avatar-size, calc(var(--event-font-size) * 2));\n    height: var(--avatar-height, var(--avatar-size, calc(var(--event-font-size) * 2)));\n    margin: 0;\n  }\n  .event-list .event:is(.type-gift, .type-guard) > .user {\n    grid-column: -2;\n    grid-row: 1;\n    max-width: 100%;\n    min-height: 0;\n    margin: 0;\n  }\n  .event-list .event:is(.type-gift, .type-guard) > .content {\n    grid-column: -2;\n    grid-row: 2;\n    display: flex;\n    flex-wrap: wrap;\n    align-items: center;\n    gap: var(--event-gap, calc(var(--event-font-size) * 0.25));\n    row-gap: var(--event-gap, calc(var(--event-font-size) * 0.125));\n    min-width: 0;\n  }\n  .event-list .event:is(.type-gift, .type-guard) .content > .price {\n    position: absolute;\n    top: 50%;\n    right: calc(\n      var(--gift-icon-size, calc(var(--event-font-size) * 2)) + var(--event-font-size) * 1.25\n    );\n    transform: translateY(-50%);\n    margin: 0;\n  }\n  .event-list .event:is(.type-gift, .type-guard) .content > :is(.gift-icon, .guard-purchase-icon) {\n    order: 1;\n    position: absolute;\n    right: calc(var(--event-font-size) * 0.75);\n    top: 50%;\n    transform: translateY(-50%);\n    width: var(--gift-icon-size, calc(var(--event-font-size) * 2));\n    height: var(--gift-icon-size, calc(var(--event-font-size) * 2));\n  }\n  .event .content > .guard-companion-days {\n    order: 0;\n    flex-basis: auto;\n    padding: 0 calc(var(--event-font-size) * 0.5);\n    border-radius: calc(var(--event-font-size) * 0.25);\n    background: color-mix(in srgb, var(--card-tone) 14%, transparent);\n    color: var(--card-tone);\n    font-size: inherit;\n  }\n  .event-list .event .blind-gift {\n    order: 2;\n    flex-basis: 100%;\n    display: inline-flex;\n    flex-wrap: wrap;\n    align-items: center;\n    gap: var(--event-gap, calc(var(--event-font-size) * 0.25));\n    margin: 0;\n  }\n  .event .blind-gift :is(.blind-price, .blind-profit) {\n    font-size: var(--price-font-size, inherit);\n  }\n\n  /* SC：信息行与正文分区，背景直接画在已有 info 上。 */\n  .event.type-superchat {\n    --card-tone: var(--price-color, #9f3a69);\n    --card-fill: #f8f0f0;\n  }\n  .event-list .event.type-superchat {\n    display: block;\n    padding: 0;\n  }\n  .event-list .event.type-superchat > .info {\n    display: flex;\n    flex-wrap: wrap;\n    align-items: center;\n    gap: var(--event-gap, calc(var(--event-font-size) * 0.5));\n    padding: var(--event-padding, calc(var(--event-font-size) * 0.5))\n      var(--event-padding, calc(var(--event-font-size) * 0.75));\n    background: color-mix(in srgb, var(--card-tone) 7%, transparent);\n    border-radius: inherit;\n    border-bottom-left-radius: 0;\n    border-bottom-right-radius: 0;\n    border-bottom: calc(var(--event-font-size) / 16) solid\n      color-mix(in srgb, var(--card-tone) 12%, transparent);\n  }\n  .event-list .event.type-superchat .info > .user {\n    flex: 1 1 calc(var(--event-font-size) * 6);\n    min-width: 0;\n    margin: 0;\n    max-width: none;\n  }\n  .event-list .event.type-superchat .info > .avatar-wrap {\n    margin: 0;\n  }\n  .event-list .event.type-superchat .info > .price {\n    margin: 0;\n  }\n  .event-list .event.type-superchat .info > .event-icon {\n    width: calc(var(--event-font-size) * 1.5);\n    height: calc(var(--event-font-size) * 1.5);\n  }\n  .event-list .event.type-superchat > .content {\n    display: block;\n    margin: 0;\n    padding: var(--event-padding, calc(var(--event-font-size) * 0.75));\n    line-height: var(--event-line-height, 1.5);\n  }\n  .event .bili-translation {\n    margin-top: calc(var(--event-font-size) * 0.5);\n    padding-top: calc(var(--event-font-size) * 0.5);\n    border-top: calc(var(--event-font-size) / 16) solid var(--card-edge);\n    color: var(--message-color, var(--text-secondary));\n    font-size: calc(var(--event-font-size) * 0.875);\n  }\n\n  /* 活动：状态位于信息行，图片与金额留在正文区域。 */\n  .event.redpocket-start {\n    --card-fill:\n      linear-gradient(var(--card-sheen), transparent calc(var(--event-font-size) * 2)), #f9f0eb;\n  }\n  .dark .event.redpocket-start {\n    --card-fill:\n      linear-gradient(var(--card-sheen), transparent calc(var(--event-font-size) * 2)), #272925;\n  }\n  .event-list .event:is(.lottery-start, .redpocket-start) {\n    display: grid;\n    grid-template-columns: minmax(0, 1fr) auto;\n    gap: var(--event-gap, calc(var(--event-font-size) * 0.125))\n      var(--event-gap, calc(var(--event-font-size) * 0.75));\n  }\n  .event-list .event:is(.lottery-start, .redpocket-start):has(> .avatar-wrap) {\n    grid-template-columns: auto minmax(0, 1fr) auto;\n  }\n  .event-list .event:is(.lottery-start, .redpocket-start) > .avatar-wrap {\n    grid-column: 1;\n    grid-row: 1 / span 2;\n    align-self: center;\n    margin: 0;\n  }\n  .event-list .event:is(.lottery-start, .redpocket-start) > :is(.user, .activity-title) {\n    grid-column: -3;\n    grid-row: 1;\n    margin: 0;\n    max-width: 100%;\n    min-height: 0;\n  }\n  .event-list .event:is(.lottery-start, .redpocket-start) > .content {\n    grid-column: -3;\n    grid-row: 2;\n  }\n  .event-list .event.redpocket-start > .content {\n    grid-column: -3 / -1;\n  }\n  .event-list .event.lottery-start > .event-icon {\n    grid-column: -2;\n    grid-row: 2;\n    align-self: center;\n    width: calc(var(--event-font-size) * 2);\n    height: calc(var(--event-font-size) * 2);\n  }\n  .event-list .event:is(.lottery-start, .redpocket-start) > .activity-status {\n    grid-column: -2;\n    grid-row: 1;\n    justify-self: end;\n    position: static;\n    align-self: start;\n    margin: 0;\n  }\n  .event\n    :is(\n      .lottery-command,\n      .lottery-required-gift,\n      .lottery-requirement,\n      .redpocket-awards,\n      .redpocket-command\n    ) {\n    display: block;\n    margin: calc(var(--event-font-size) * 0.125) 0 0;\n    line-height: inherit;\n  }\n  .event :is(.lottery-command, .redpocket-command) > .prefix {\n    margin-right: calc(var(--event-font-size) * 0.25);\n  }\n  .event .redpocket {\n    display: block;\n  }\n  .event :is(.lottery-name, .redpocket-name, .activity-prize) {\n    color: inherit;\n    font-weight: 700;\n  }\n\n  .event-list .event.redpocket-start .redpocket {\n    position: relative;\n    min-height: calc(var(--event-font-size) * 2);\n    padding-right: calc(var(--event-font-size) * 6.75);\n  }\n  .event-list .event.redpocket-start .redpocket > .price {\n    position: absolute;\n    top: 50%;\n    right: calc(var(--event-font-size) * 2.5);\n    transform: translateY(-50%);\n    margin: 0;\n  }\n  .event-list .event.redpocket-start .activity-action > .event-icon {\n    position: absolute;\n    top: 50%;\n    right: 0;\n    transform: translateY(-50%);\n    width: calc(var(--event-font-size) * 2);\n    height: calc(var(--event-font-size) * 2);\n    margin: 0;\n  }\n  .event .activity-status {\n    padding: 0 calc(var(--event-font-size) * 0.375);\n    border-radius: calc(var(--event-font-size) * 0.375);\n    background: var(--card-surface);\n    box-shadow: inset 0 0 0 calc(var(--event-font-size) / 16)\n      color-mix(in srgb, var(--card-tone) 20%, transparent);\n    color: var(--card-tone);\n    font-size: calc(var(--event-font-size) * 0.75);\n  }\n  .event .activity-status.activity-urgent {\n    color: var(--status-danger);\n  }\n  .event-list .event.type-superchat > .content > .message {\n    display: inline;\n  }\n\n  .event-list .event.lottery-start > .activity-title {\n    padding-left: 0;\n  }\n\n  /* 开奖：为名单留出首行空间，展开内容保持在原 details 中。 */\n  .event-list .event:is(.lottery-result, .redpocket-result) {\n    display: grid;\n    grid-template-columns: auto minmax(0, 1fr);\n    gap: 0 calc(var(--event-font-size) * 0.5);\n  }\n  .event-list .event:is(.lottery-result, .redpocket-result) > .event-icon {\n    grid-column: 1;\n    grid-row: 1 / span 2;\n    align-self: center;\n    width: calc(var(--event-font-size) * 1.5);\n    height: calc(var(--event-font-size) * 1.5);\n    margin: 0;\n  }\n  .event-list .event:is(.lottery-result, .redpocket-result) > .result-title {\n    grid-column: 2;\n    grid-row: 1;\n    display: block;\n    padding: 0;\n    font-size: inherit;\n    color: inherit;\n  }\n  .event-list .event:is(.lottery-result, .redpocket-result) > .content {\n    display: block;\n    grid-column: 2;\n    grid-row: 2;\n  }\n  .event .result-description {\n    font-weight: 700;\n    color: var(--text-body);\n  }\n  .event .winner-list-toggle {\n    top: calc(var(--event-font-size) * 0.5);\n    right: calc(var(--event-font-size) * 0.75);\n    font-size: calc(var(--event-font-size) * 0.75);\n    line-height: 1.5;\n  }\n  .event .winner-list-items {\n    margin-top: calc(var(--event-font-size) * 0.5);\n    padding-top: calc(var(--event-font-size) * 0.5);\n    border-color: var(--card-edge);\n  }\n  .event .winner-list-item {\n    font-size: calc(var(--event-font-size) * 0.875);\n  }\n\n  .event-list .event:is(.lottery-result, .redpocket-result):has(.winner-list) > .result-title {\n    padding-right: calc(var(--event-font-size) * 2.5);\n  }\n\n  /* 成就：两行文案、右侧数字与原有官方图片。 */\n  .event-list .event.type-guard-honor {\n    --card-tone: var(--card-gold);\n    --card-fill: #f4f1e7;\n    display: flex;\n    align-items: center;\n    gap: var(--event-gap, calc(var(--event-font-size) * 0.5));\n    padding: var(--event-padding, calc(var(--event-font-size) * 0.75));\n    border-radius: var(--event-font-size);\n    box-shadow: inset 0 0 0 calc(var(--event-font-size) / 16)\n      color-mix(in srgb, var(--card-tone) 36%, transparent);\n  }\n  .dark .event.type-guard-honor {\n    --card-fill: #2c2f24;\n  }\n  .event-list .event.type-guard-honor > .avatar-wrap {\n    flex: none;\n    width: var(--avatar-size, calc(var(--event-font-size) * 2));\n    height: var(\n      --avatar-height,\n      var(--avatar-size, calc(var(--event-font-size) * 2))\n    );\n    margin: 0;\n  }\n  .event-list .event.type-guard-honor > .content {\n    flex: 1;\n    min-width: 0;\n    padding-right: calc(var(--event-font-size) * 5);\n  }\n  .event .honor-heading {\n    font-size: inherit;\n    line-height: 1.5;\n  }\n  .event .honor-summary {\n    margin-top: 0;\n    font-size: inherit;\n    line-height: 1.5;\n  }\n  .event-list .event.type-guard-honor .honor-icon {\n    position: absolute;\n    right: calc(var(--event-font-size) * 0.75);\n    top: 50%;\n    transform: translateY(-50%);\n    width: calc(var(--event-font-size) * 3.5);\n    height: calc(var(--event-font-size) * 3.5);\n    opacity: 0.3;\n  }\n  .event-list .event.type-guard-honor .honor-milestone {\n    position: absolute;\n    right: calc(var(--event-font-size) * 0.75);\n    top: 50%;\n    transform: translateY(-50%);\n    font-size: calc(var(--event-font-size) * 2);\n    line-height: 1;\n    margin: 0;\n    color: var(--message-color, var(--card-tone));\n  }\n  /* 四圈半径为基准字号的2.5、4.375、6.25、8.125倍，透明度沿用原图。 */\n  .event-list .event.type-guard-honor::before {\n    content: \"\";\n    display: block;\n    position: absolute;\n    inset: 0;\n    border-radius: inherit;\n    z-index: -1;\n    pointer-events: none;\n    background: var(--card-tone);\n    mask-image: url(\"data:image/svg+xml,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20viewBox%3D'0%200%20264%20264'%3E%3Cg%20fill%3D'none'%20stroke%3D'black'%20stroke-width%3D'1'%3E%3Ccircle%20cx%3D'132'%20cy%3D'132'%20r%3D'40'%20stroke-opacity%3D'.22'%2F%3E%3Ccircle%20cx%3D'132'%20cy%3D'132'%20r%3D'70'%20stroke-opacity%3D'.17'%2F%3E%3Ccircle%20cx%3D'132'%20cy%3D'132'%20r%3D'100'%20stroke-opacity%3D'.12'%2F%3E%3Ccircle%20cx%3D'132'%20cy%3D'132'%20r%3D'130'%20stroke-opacity%3D'.07'%2F%3E%3C%2Fg%3E%3C%2Fsvg%3E\");\n    mask-repeat: no-repeat;\n    mask-size: calc(var(--event-font-size) * 16.5) calc(var(--event-font-size) * 16.5);\n    mask-position: calc(\n        var(--event-padding, calc(var(--event-font-size) * 0.75)) +\n          var(--avatar-size, calc(var(--event-font-size) * 2)) / 2 - var(--event-font-size) * 8.25\n      )\n      center;\n  }\n  .event-list .event.type-guard-honor:not(:has(> .avatar-wrap))::before {\n    display: none;\n  }\n  .event-list .event.type-guard-honor::after {\n    inset: calc(var(--event-font-size) * 0.25);\n    border-radius: calc(var(--event-font-size) * 0.75);\n    box-shadow: inset 0 0 0 calc(var(--event-font-size) / 16)\n      color-mix(in srgb, var(--card-tone) 18%, transparent);\n  }\n\n  /* 系统消息用自然行流，开播与下播时间靠右。 */\n  .event:is(.type-system, .type-live-status, .type-unknown) {\n    --card-fill: var(--card-surface);\n  }\n  .event-list .event:is(.type-system, .type-live-status, .type-unknown) {\n    padding: var(--event-padding, calc(var(--event-font-size) * 0.5))\n      var(--event-padding, calc(var(--event-font-size) * 0.625));\n    display: block;\n    border-radius: calc(var(--event-font-size) * 0.5);\n    box-shadow: inset 0 0 0 calc(var(--event-font-size) / 16) var(--card-edge);\n  }\n  .event-list .event .system-message {\n    font-size: var(--event-font-size);\n    line-height: calc(var(--event-font-size) * var(--event-line-height, 1.5));\n    color: var(--message-color, var(--text-secondary));\n    font-weight: 500;\n  }\n  .event-list .event .system-message-copy {\n    flex: 1;\n    min-width: 0;\n  }\n  .event-list .event .system-message-detail {\n    margin-top: calc(var(--event-font-size) * 0.125);\n    font-size: calc(var(--event-font-size) * 0.875);\n    line-height: calc(var(--event-font-size) * 1.5);\n    font-weight: 500;\n    color: var(--message-color, var(--text-muted));\n  }\n  .event-list .event:is(.live-start, .live-end) .system-message-title {\n    font-weight: 500;\n  }\n  .event .lifecycle-time {\n    float: right;\n    margin: 0 0 0 calc(var(--event-font-size) * 0.75);\n    font-size: inherit;\n    line-height: inherit;\n    font-weight: inherit;\n    color: inherit;\n  }\n  .event:is(.live-start, .system-room-silent-off, .system-admin-appointed, .system-admin-list-updated) {\n    --card-tone: #20673f;\n  }\n  .dark .event:is(.live-start, .system-room-silent-off, .system-admin-appointed, .system-admin-list-updated) {\n    --card-tone: #7fcaa0;\n  }\n  .event:is(.system-user-block, .system-room-silent-on) {\n    --card-tone: #7e4f05;\n  }\n  .dark .event:is(.system-user-block, .system-room-silent-on) {\n    --card-tone: #e6bb78;\n  }\n  .event.live-end {\n    --card-tone: var(--native-system-tone);\n  }\n  .event-list .event:is(.live-start, .live-end, .system-room-change, .system-room-silent-off) .system-message {\n    font-size: calc(var(--event-font-size) * 0.875);\n    color: var(--message-color, var(--text-muted));\n  }\n  .event-list .event:is(.live-start, .live-end) .system-message {\n    color: var(--message-color, var(--card-tone));\n  }\n  .event-list .event:is(.system-user-block, .system-room-silent-on, .system-room-silent-off, .system-admin-appointed) .system-message-title > .message {\n    color: var(--message-color, var(--card-tone));\n  }\n  .event-list .event:is(.system-admin-revoked, .system-admin-list-updated, .system-room-change) .system-message-title {\n    color: var(--message-color, var(--text-body));\n  }\n  .event-list .event:is(.live-warning, .live-cutoff) .system-message {\n    color: var(--text-body);\n  }\n  .event-list .event:is(.live-warning, .live-cutoff) .system-message-title {\n    color: var(--message-color, #7e4f05);\n  }\n  .dark .event-list .event:is(.live-warning, .live-cutoff) .system-message-title {\n    color: var(--message-color, #e6bb78);\n  }\n  .event-list .event:is(.live-warning, .live-cutoff) .system-message-detail {\n    color: var(--message-color, var(--text-secondary));\n  }\n  .event.live-warning {\n    --card-tone: #7e4f05;\n  }\n  .event.live-cutoff {\n    --card-tone: #a02c2c;\n  }\n  .dark .event.live-warning {\n    --card-tone: #e6bb78;\n  }\n  .dark .event.live-cutoff {\n    --card-tone: #ee8f8f;\n  }\n  .event-list .event:is(.live-warning, .live-cutoff) {\n    --card-fill: color-mix(in srgb, var(--card-tone) 6%, var(--card-surface));\n    box-shadow: inset 0 0 0 calc(var(--event-font-size) / 16)\n      color-mix(in srgb, var(--card-tone) 18%, var(--card-edge));\n  }\n  .event-list .event:is(.live-warning, .live-cutoff) .system-message {\n    font-size: inherit;\n    font-weight: 700;\n  }\n  .event-list .event .system-message-icon {\n    width: var(--event-font-size);\n    height: calc(var(--event-font-size) * var(--event-line-height, 1.5));\n    margin: 0;\n    color: var(--card-tone);\n  }\n\n  /* 置顶沿用胶囊结构，不应用正文分区。 */\n  .event.event-sticky {\n    display: flex;\n    flex-wrap: nowrap;\n    align-items: center;\n    width: max-content;\n    padding: var(--event-padding, calc(var(--event-font-size) * 0.25));\n    padding-right: var(--event-padding, calc(var(--event-font-size) * 0.5));\n    border-radius: var(--event-font-size);\n    color: var(--message-color, var(--card-tone));\n    background-image: none;\n    --price-gradient-background:\n      color-mix(in srgb, var(--card-tone) var(--card-tint), var(--price-tier-background-color));\n  }\n  .event.event-sticky::before {\n    content: \"\";\n    display: block;\n    position: absolute;\n    inset: 0;\n    border-radius: inherit;\n    background: linear-gradient(var(--card-sheen), transparent);\n    pointer-events: none;\n    z-index: -1;\n  }\n  .event.event-sticky :is(.price, .lottery) {\n    font-size: var(--price-font-size, var(--event-font-size));\n    line-height: 1;\n    font-weight: 700;\n    color: var(--price-color, var(--message-color, var(--card-tone)));\n  }\n  .event.event-sticky > .content {\n    flex-wrap: nowrap;\n  }\n  .event.event-sticky .blind-gift {\n    flex: none;\n  }\n  .event.event-sticky .avatar-wrap {\n    align-self: center;\n    width: var(--avatar-size, calc(var(--event-font-size) * 1.5));\n    height: var(--avatar-height, var(--avatar-size, calc(var(--event-font-size) * 1.5)));\n  }\n\n  /* 窄幅不保留侧栏，价格和正文部件各自自然换行。 */\n  @container native-events (max-width: 20em) {\n    .event-list .event:is(.type-gift, .type-guard, .lottery-start, .redpocket-start) > .content {\n      grid-column: 1 / -1;\n      grid-row: 2;\n    }\n    .event-list .event:is(.type-gift, .type-guard, .lottery-start, .redpocket-start) > .avatar-wrap {\n      grid-row: 1;\n    }\n    .event-list .event:is(.type-gift, .type-guard) {\n      padding-right: var(--event-padding, calc(var(--event-font-size) * 0.75));\n    }\n    .event-list .event:is(.type-gift, .type-guard) .content > :is(.price, .gift-icon, .guard-purchase-icon) {\n      position: static;\n      transform: none;\n      margin: 0;\n    }\n    .event-list .event.redpocket-start .redpocket > .price,\n    .event-list .event.redpocket-start .activity-action > .event-icon {\n      position: static;\n      transform: none;\n    }\n    .event-list .event.redpocket-start .redpocket {\n      padding-right: 0;\n      min-height: 0;\n    }\n    .event-list .event:is(.lottery-start, .redpocket-start):has(> .avatar-wrap) {\n      grid-template-columns: auto minmax(0, 1fr);\n    }\n    .event-list .event:is(.lottery-start, .redpocket-start) > :is(.user, .activity-title) {\n      grid-column: 1;\n    }\n    .event-list .event:is(.lottery-start, .redpocket-start):has(> .avatar-wrap)\n      > :is(.user, .activity-title) {\n      grid-column: 2;\n    }\n    .event-list .event:is(.lottery-start, .redpocket-start) > .activity-status {\n      position: static;\n      grid-column: 1 / -1;\n      grid-row: 2;\n      margin: 0;\n    }\n    .event-list .event:is(.lottery-start, .redpocket-start) > .content {\n      grid-row: 3;\n    }\n    .event-list .event.lottery-start > .event-icon {\n      grid-row: 3;\n      grid-column: 1 / -1;\n      justify-self: end;\n    }\n    .event-list .event.lottery-start > .content {\n      padding-right: calc(var(--event-font-size) * 2.5);\n    }\n    .event-list .event:is(.lottery-result, .redpocket-result) > .result-title {\n      font-size: calc(var(--event-font-size) * 0.875);\n    }\n    .event-list .event.type-guard-honor {\n      flex-wrap: wrap;\n    }\n    .event-list .event.type-guard-honor > .content {\n      flex-basis: 100%;\n      padding-right: 0;\n    }\n    .event-list .event.type-guard-honor .honor-milestone {\n      position: static;\n      display: inline;\n      font-size: calc(var(--event-font-size) * 1.5);\n      transform: none;\n      margin-left: calc(var(--event-font-size) * 0.25);\n    }\n    .event-list .event.type-guard-honor .honor-icon {\n      top: calc(var(--event-font-size) * 0.5);\n      transform: none;\n      width: calc(var(--event-font-size) * 2.5);\n      height: calc(var(--event-font-size) * 2.5);\n    }\n    .event-list .event.type-guard-honor::before {\n      mask-position: calc(\n          var(--event-padding, calc(var(--event-font-size) * 0.75)) +\n            var(--avatar-size, calc(var(--event-font-size) * 2)) / 2 - var(--event-font-size) *\n            8.25\n        )\n        calc(\n          var(--event-padding, calc(var(--event-font-size) * 0.75)) +\n            var(--avatar-size, calc(var(--event-font-size) * 2)) / 2 - var(--event-font-size) *\n            8.25\n        );\n    }\n  }\n\n  .event-list .event:is(\n      .type-gift,\n      .type-guard,\n      .type-superchat,\n      .type-lottery,\n      .type-redpocket,\n      .type-guard-honor\n    )\n    > .time {\n    display: none;\n  }\n}\n";
